from google.cloud import translate_v3 as translate

def welcome_translate(text_to_translate: str, target_language_code: str, source_language_code: Optional[str] = None) -> Dict[str, Any]:
    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT_ID")
    if not project_id:
        return {"error": "GOOGLE_CLOUD_PROJECT_ID environment variable not set."}

    client = translate.TranslationServiceClient()
    location = "global"
    parent = f"projects/{project_id}/locations/{location}"

    try:
        # Detail on supported formats: https://cloud.google.com/translate/docs/supported-formats
        response = client.translate_text(
            request={
                "parent": parent,
                "contents": [text_to_translate],
                "mime_type": "text/plain",
                "source_language_code": source_language_code, # Optional. If not set, the API will try to detect.
                "target_language_code": target_language_code,
            }
        )

        translated_text = response.translations[0].translated_text if response.translations else text_to_translate
        return {"translated_text": translated_text}

    except Exception as e:
        return {"error": f"Google Cloud Translate API failed: {str(e)}"}",
