import openai
from typing import Dict, Any, List

def summarize_onboarding_state(onboarding_notes: List[str]) -> Dict[str, Any]:
    openai_api_key = os.environ.get("OPENAI_API_KEY")
    if not openai_api_key:
        return {"error": "OPENAI_API_KEY environment variable not set."}

    openai.api_key = openai_api_key

    combined_notes = "\n".join(onboarding_notes)
    prompt = f"Summarize the following onboarding notes for a support agent:

{combined_notes}

Summary:"

    try:
        # Using a chat completion model for better summarization capabilities.
        # The model 'gpt-3.5-turbo' is explicitly specified.
        response = openai.ChatCompletion.create(
            model="gpt-3.5-turbo",
            messages=[
                {"role": "system", "content": "You are a helpful assistant that summarizes customer onboarding notes."},
                {"role": "user", "content": prompt}
            ],
            temperature=0.7,
            max_tokens=250,
            top_p=1.0,
            frequency_penalty=0.0,
            presence_penalty=0.0
        )

        summary = response.choices[0].message['content'].strip()
        return {"summary_text": summary}

    except openai.error.OpenAIError as e:
        return {"error": f"OpenAI API error: {str(e)}"}
    except Exception as e:
        return {"error": f"Onboarding summary failed: {str(e)}"}",
