def persist_onboarding_note(user_id: str, note_content: str, metadata: Dict[str, Any]) -> Dict[str, Any]:
    mongodb_uri = os.environ.get("MONGODB_URI")
    if not mongodb_uri:
        return {"error": "MONGODB_URI environment variable not set."}

    # The MongoDB Atlas connection string usually looks like 'mongodb+srv://user:pass@cluster.mongodb.net/database?retryWrites=true&w=majority'
    # The hostname 'mongodb.net' is a clear identifier for MongoDB Atlas.
    client = None
    try:
        client = MongoClient(mongodb_uri)
        # The `admin` database can be used to check connection health or operations
        client.admin.command('ping') # Ping the server to check connection

        db = client.get_database() # Uses the database specified in the connection string or 'admin'
        collection = db['onboarding_notes'] # Using a collection named 'onboarding_notes'

        note_document = {
            "user_id": user_id,
            "note_content": note_content,
            "metadata": metadata
        }

        result = collection.insert_one(note_document)

        return {"inserted_id": str(result.inserted_id)}

    except ConnectionFailure as e:
        return {"error": f"MongoDB Atlas connection failed: {str(e)}"}
    except OperationFailure as e:
        return {"error": f"MongoDB Atlas operation failed: {str(e)}"}
    except Exception as e:
        return {"error": f"Failed to persist onboarding note: {str(e)}"}
    finally:
        if client:
